<script setup lang="ts">
import { computed, ref } from 'vue';
import { Head, Link, router, useForm, usePoll } from '@inertiajs/vue3';
import AppLayout from '@/layouts/AppLayout.vue';
import Heading from '@/components/Heading.vue';
import { index, show, record } from '@/routes/transfers';
import { show as showCase } from '@/routes/workspace';
import { toDateTimeInput } from '@/lib/dentists';

defineOptions({ layout: AppLayout });
type Attempt = { id: number; interaction_id: number; revision: number; sequence: number; status: string; destination_masked: string | null; match_status: string; dentist: { name: string } | null; human_outcome: string; acceptance_confidence: string; timing_quality: string; failure_reason: string | null; fallback_status: string; dial_started_at: string | null; ringing_at: string | null; answered_at: string | null; ended_at: string | null; transfer_completed_at: string | null; human_accepted_at: string | null; dial_to_answer_seconds: number | null; ringing_seconds: number | null; mobile_connected_seconds: number | null; private_handover_seconds: number | null; consultation_seconds: number | null; session: { status: string; started_at: string; ended_at: string | null; consultation_seconds: number | null; intervals: { bridge_uniqueid: string; started_at: string; ended_at: string | null; duration_seconds: number | null }[] } | null };
const props = defineProps<{ attempt: Attempt; events: { data: { id: number; kind: string; outcome: string | null; note: string | null; occurred_at: string; recorded_at: string; recorded_by: number | null }[]; prev_page_url: string | null; next_page_url: string | null }; caseId: number | null; canRecord: boolean; outcomes: string[]; fallbacks: string[]; related: { id: number; sequence: number; status: string; retry_of_id: number | null }[]; diagnostics: { code: string; category: string; subject: string }[] }>();
const form = useForm({ kind: 'operator_outcome', outcome: 'unknown', occurred_at: toDateTimeInput(new Date(props.attempt.answered_at ?? props.attempt.dial_started_at ?? Date.now())), note: '', attested: false });
const choices = computed(() => form.kind === 'fallback' ? props.fallbacks : props.outcomes);
const polling = ref(false);
const poll = usePoll(3000, { only: ['attempt', 'related', 'diagnostics'] }, { autoStart: false });
function toggle() { polling.value = !polling.value; if (polling.value) poll.start(); else poll.stop(); }
function save() {
    form.transform((data) => ({ ...data, occurred_at: new Date(data.occurred_at).toISOString(), revision: props.attempt.revision })).post(record.url(props.attempt.id), { preserveScroll: true, onSuccess: () => { form.note = ''; form.attested = false; } });
}
function label(value: string) { return value.replaceAll('_', ' '); }
const timings = computed(() => [
    ['Dial started', props.attempt.dial_started_at], ['Ringing indication', props.attempt.ringing_at], ['Mobile answered', props.attempt.answered_at], ['Transfer completed (PBX)', props.attempt.transfer_completed_at], ['Human accepted (operator)', props.attempt.human_accepted_at], ['Mobile ended', props.attempt.ended_at],
    ['Dial to answer (s)', props.attempt.dial_to_answer_seconds], ['Observed ringing (s)', props.attempt.ringing_seconds], ['Mobile connected (s)', props.attempt.mobile_connected_seconds], ['Private handover (s)', props.attempt.private_handover_seconds], ['Caller/dentist bridge (s)', props.attempt.consultation_seconds],
]);
</script>

<template>
    <div class="space-y-6 p-6">
        <Head :title="`Transfer attempt #${attempt.id}`" />
        <Heading :title="`Attempt #${attempt.id} · ${label(attempt.status)}`" :description="`Interaction #${attempt.interaction_id} · try ${attempt.sequence} · ${attempt.destination_masked ?? 'Destination not identifiable'} · ${attempt.match_status} directory match`" />
        <nav class="flex flex-wrap gap-4 text-sm"><Link :href="index()">All transfers</Link><Link v-if="caseId" :href="showCase(caseId)">Verified case and SBAR</Link><button type="button" @click="router.reload()">Refresh evidence</button><button type="button" @click="toggle">{{ polling ? 'Pause evidence refresh' : 'Resume evidence refresh' }}</button></nav>
        <section class="space-y-3 rounded-xl border bg-card p-5"><h2 class="text-lg font-semibold">Evidence and confidence</h2><p>Directory dentist: {{ attempt.dentist?.name ?? 'Unknown destination — reconcile with the approved directory' }}</p><p>Human outcome: <strong>{{ label(attempt.human_outcome) }}</strong> · acceptance confidence: <strong>{{ label(attempt.acceptance_confidence) }}</strong> · timestamp basis: {{ attempt.timing_quality }}</p><p v-if="attempt.failure_reason">Failure evidence: {{ attempt.failure_reason }}</p><p>Fallback intent: {{ label(attempt.fallback_status) }}. This record does not dial, reserve a dentist, book a callback or deliver a referral.</p><p class="text-sm text-muted-foreground">Network ANSWER may be voicemail. Only an authorised operator's confirmation establishes human acceptance. Caller/mobile bridge time is an observation, not proof of a human consultation. Missing ringing indications remain unknown.</p><dl class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><div v-for="[name, value] in timings" :key="String(name)"><dt class="text-sm text-muted-foreground">{{ name }}</dt><dd class="break-words font-medium">{{ value ?? 'Not observed' }}</dd></div></dl></section>
        <section v-if="attempt.session" class="space-y-3 rounded-xl border bg-card p-5"><h2 class="text-lg font-semibold">Consultation intervals · {{ label(attempt.session.status) }}</h2><p>Only two-party caller/mobile bridge intervals are counted; private handover, holds and ambiguous bridges are excluded. Overlapping or incomplete evidence leaves duration unknown.</p><article v-for="(interval, position) in attempt.session.intervals" :key="position" class="rounded border p-3 text-sm">{{ interval.bridge_uniqueid }} · {{ interval.started_at }} → {{ interval.ended_at ?? 'open / missing end' }} · {{ interval.duration_seconds ?? 'unknown' }} seconds</article></section>
        <section class="space-y-3 rounded-xl border bg-card p-5"><h2 class="text-lg font-semibold">Retries and fallback</h2><p class="text-sm text-muted-foreground">Try order follows observed mobile-leg dial starts in this interaction. A later try may overlap an earlier call; the sequence does not prove an earlier attempt failed.</p><ul class="grid gap-2"><li v-for="item in related" :key="item.id"><Link :href="show(item.id)">Try {{ item.sequence }} · #{{ item.id }} · {{ label(item.status) }}</Link><span v-if="item.retry_of_id" class="text-sm text-muted-foreground"> · previous attempt #{{ item.retry_of_id }}</span></li></ul></section>
        <section class="space-y-4 rounded-xl border bg-card p-5"><h2 class="text-lg font-semibold">Record operator evidence</h2><p v-if="!canRecord" class="text-sm text-muted-foreground">Confirmation requires transfer-edit permission and access to the verified case associated with this interaction. Operator notes are visible only within that case access boundary.</p>
            <form v-if="canRecord" class="grid gap-4" @submit.prevent="save"><label class="grid gap-2">Evidence type<select v-model="form.kind" class="rounded border bg-background p-2" @change="form.outcome = form.kind === 'fallback' ? 'pending' : 'unknown'"><option value="operator_outcome">Human answer / transfer outcome</option><option value="fallback">Fallback intent</option></select></label><label class="grid gap-2">Outcome<select v-model="form.outcome" class="rounded border bg-background p-2"><option v-for="choice in choices" :key="choice" :value="choice">{{ label(choice) }}</option></select></label><label class="grid gap-2">Actual event time (your local time)<input v-model="form.occurred_at" type="datetime-local" step="1" required class="rounded border bg-background p-2" /></label><label class="grid gap-2">Factual confirmation / correction reason<textarea v-model="form.note" required maxlength="2000" rows="3" class="rounded border bg-background p-2"></textarea></label><label class="flex items-start gap-2"><input v-model="form.attested" type="checkbox" required class="mt-1" />I verified this outcome and recorded the actual action time. A network answer alone is not dentist acceptance.</label><p v-for="(error, key) in form.errors" :key="key" role="alert" class="text-sm text-red-600">{{ error }}</p><button :disabled="form.processing" class="w-fit rounded bg-primary px-4 py-2 text-primary-foreground">Append operator evidence</button></form>
        </section>
        <section class="space-y-3 rounded-xl border bg-card p-5"><h2 class="text-lg font-semibold">Event history</h2><p class="text-sm text-muted-foreground">Corrections append evidence. The most recently recorded operator outcome is used; original confirmations remain in history. Event time and recording time are kept separately.</p><article v-for="event in events.data" :key="event.id" class="space-y-1 border-t pt-3"><p class="font-medium">{{ label(event.kind) }} · {{ event.outcome ? label(event.outcome) : 'unknown' }}</p><p class="text-xs text-muted-foreground">Occurred {{ event.occurred_at }} · recorded {{ event.recorded_at }}<span v-if="event.recorded_by"> · operator #{{ event.recorded_by }}</span></p><p v-if="event.note" class="whitespace-pre-wrap">{{ event.note }}</p></article><nav class="flex gap-4 text-sm"><Link v-if="events.prev_page_url" :href="events.prev_page_url">Previous events</Link><Link v-if="events.next_page_url" :href="events.next_page_url">More events</Link></nav></section>
        <section v-if="diagnostics.length" class="space-y-2 rounded-xl border border-amber-500 p-5"><h2 class="font-semibold">Evidence requiring review</h2><p v-for="(item, position) in diagnostics" :key="position" class="text-sm">{{ item.category }} · {{ label(item.code) }}</p></section>
    </div>
</template>
